function hash632(x){let h=2166136261;for(const c of String(x)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function sourceMaterial632(s){return {authentic:true,synthetic:false,source_id:s.id,label:`${s.canonical_ref} · ${s.title}`,text:s.original_text,translation:s.translation_text,source_type:s.source_type,language:s.language,author:s.author,period:s.period,place:s.place,original_source_name:s.original_source_name,original_source_url:s.original_source_url,translation_source_name:s.translation_source_name,translation_source_url:s.translation_source_url,translation_credit:s.translation_credit,context_hint:s.context_hint,language_hint:s.language_hint,analytic_hint:s.analytic_hint,scaffold:s.scaffold||[]}}
function coherentBundle632(moduleId,difficulty,seed){
  const all=(window.V6_AUTHENTIC_SOURCES||[]).filter(s=>s.primary&&s.ready),byId=new Map(all.map(s=>[s.id,s]));
  const valid=THEME_BUNDLES632.map(b=>({...b,sources:b.ids.map(id=>byId.get(id)).filter(Boolean)})).filter(b=>b.sources.length>=2);
  const pool=valid.filter(b=>b.sources.some(s=>(s.recommended_modules||[]).includes(moduleId)));
  const choices=pool.length?pool:valid; const bundle=choices[hash632(`${moduleId}|${seed}`)%choices.length];
  const count=Math.min(bundle.sources.length,difficulty>=5?4:difficulty>=3?3:2);
  return {theme:bundle.title,sources:bundle.sources.slice(0,count)};
}
